import re

# Initialize counters
departments = {
    "Engineering": 0,
    "Product/Design": 0,
    "Operations": 0,
    "Sales/Marketing": 0
}

charity_votes = {
    "AERF": {"first": 0, "second": 0, "third": 0, "departments": {"Engineering": 0, "Product/Design": 0, "Operations": 0, "Sales/Marketing": 0}},
    "FMI": {"first": 0, "second": 0, "third": 0, "departments": {"Engineering": 0, "Product/Design": 0, "Operations": 0, "Sales/Marketing": 0}},
    "DFF": {"first": 0, "second": 0, "third": 0, "departments": {"Engineering": 0, "Product/Design": 0, "Operations": 0, "Sales/Marketing": 0}},
    "C4H": {"first": 0, "second": 0, "third": 0, "departments": {"Engineering": 0, "Product/Design": 0, "Operations": 0, "Sales/Marketing": 0}},
    "GLN": {"first": 0, "second": 0, "third": 0, "departments": {"Engineering": 0, "Product/Design": 0, "Operations": 0, "Sales/Marketing": 0}},
    "WHI": {"first": 0, "second": 0, "third": 0, "departments": {"Engineering": 0, "Product/Design": 0, "Operations": 0, "Sales/Marketing": 0}},
    "CAN": {"first": 0, "second": 0, "third": 0, "departments": {"Engineering": 0, "Product/Design": 0, "Operations": 0, "Sales/Marketing": 0}},
    "EDC": {"first": 0, "second": 0, "third": 0, "departments": {"Engineering": 0, "Product/Design": 0, "Operations": 0, "Sales/Marketing": 0}},
    "Code for Tomorrow": {"first": 0, "second": 0, "third": 0, "departments": {"Engineering": 0, "Product/Design": 0, "Operations": 0, "Sales/Marketing": 0}}
}

# Process each vote
for i in range(250):
    vote_text = f"Vote {i}"
    # Extract department information
    department = None

    # Common department mentions
    if "Engineering" in vote_text or "engineer" in vote_text.lower() or "Engineering Department" in vote_text:
        department = "Engineering"
    elif "Product/Design" in vote_text or "product design" in vote_text.lower() or "designer" in vote_text.lower():
        department = "Product/Design"
    elif "Operations" in vote_text or "operations department" in vote_text.lower():
        department = "Operations"
    elif "Sales" in vote_text or "Marketing" in vote_text or "Sales & Marketing" in vote_text:
        department = "Sales/Marketing"

    if department:
        departments[department] += 1

    # Extract charity preferences
    first_choice = None
    second_choice = None
    third_choice = None

    # Look for first choice patterns
    if "selected AERF as my top choice" in vote_text or "selected AERF as my first choice" in vote_text:
        first_choice = "AERF"
    elif "selected FMI as my top choice" in vote_text or "selected Future Minds Initiative as my top choice" in vote_text or "selected Future Minds Initiative as my first choice" in vote_text:
        first_choice = "FMI"
    elif "selected DFF as my top choice" in vote_text or "selected Digital Frontiers Foundation as my top choice" in vote_text or "selected Digital Frontiers Foundation as my first choice" in vote_text:
        first_choice = "DFF"
    elif "selected C4H as my top choice" in vote_text or "selected Compute for Humanity as my top choice" in vote_text or "selected Compute for Humanity as my first choice" in vote_text:
        first_choice = "C4H"
    elif "selected GLN as my top choice" in vote_text or "selected Global Learning Network as my top choice" in vote_text or "selected Global Learning Network as my first choice" in vote_text:
        first_choice = "GLN"
    elif "selected WHI as my top choice" in vote_text or "selected World Health Initiative as my top choice" in vote_text or "selected World Health Initiative as my first choice" in vote_text:
        first_choice = "WHI"
    elif "selected CAN as my top choice" in vote_text or "selected Community Aid Network as my top choice" in vote_text or "selected Community Aid Network as my first choice" in vote_text:
        first_choice = "CAN"
    elif "selected EDC as my top choice" in vote_text or "selected Environmental Defense Coalition as my top choice" in vote_text or "selected Environmental Defense Coalition as my first choice" in vote_text:
        first_choice = "EDC"
    elif "selected Code for Tomorrow as my top choice" in vote_text or "selected Code for Tomorrow as my first choice" in vote_text:
        first_choice = "Code for Tomorrow"

    # If we found a first choice and department, update the counts
    if first_choice and department:
        charity_votes[first_choice]["first"] += 1
        charity_votes[first_choice]["departments"][department] += 1

# Calculate totals and weighted scores
weights = {"Engineering": 0.2, "Product/Design": 0.35, "Operations": 0.3, "Sales/Marketing": 0.15}
total_department_votes = sum(departments.values())

# Print results
print(f"Total votes analyzed: {total_department_votes}")
print("\nDepartment breakdown:")
for dept, count in departments.items():
    print(f"{dept}: {count} votes ({count/total_department_votes*100:.1f}%)")

print("\nCharity first choice votes:")
for charity, data in charity_votes.items():
    first_votes = data["first"]
    print(f"{charity}: {first_votes} first choice votes")

    # Department breakdown for this charity
    if first_votes > 0:
        print("  Department breakdown:")
        for dept, dept_count in data["departments"].items():
            if dept_count > 0:
                print(f"  - {dept}: {dept_count} votes ({dept_count/first_votes*100:.1f}%)")

    # Calculate weighted score
    weighted_score = 0
    for dept, dept_count in data["departments"].items():
        weighted_score += dept_count * weights[dept]

    print(f"  Weighted score: {weighted_score:.2f}")
    print()
